private boolean isAncestorOf(StateNode node) {
        while (node != null) {
            if (node == this) {
                return true;
            }
            node = node.getParent();
        }

        return false;
    }

void visitNodeTreeBottomUp(Consumer<StateNode> visitor) {
        LinkedList<StateNode> stack = new LinkedList<>();
        stack.add(this);
        // not done inside loop to please Sonarcube
        forEachChild(stack::addFirst);
        StateNode previousParent = this;
        Set<StateNode> childrenAdded = new HashSet<>();

        while (!stack.isEmpty()) {
            StateNode current = stack.getFirst();
            assert current != null;
            if (current == previousParent) {
                visitor.accept(stack.removeFirst());
                previousParent = current.getParent();
            } else if (childrenAdded.contains(current)) {
                previousParent = current;
            } else {
                current.forEachChild(stack::addFirst);
                childrenAdded.add(current);
                previousParent = current;
            }
        }
    }

@Override
        public boolean isAttached() {
            // the method is called from the super class (which is bad: call
            // overridden method at the class init phase), so there the field
            // from enclosing class is used because it's already initialized at
            // the class constructor call.
            return isRootAttached;
        }

