public void runExecutionsBeforeClientResponse() {
        while (true) {
            List<StateTree.BeforeClientResponseEntry> callbacks = flushCallbacks();
            if (callbacks.isEmpty()) {
                return;
            }
            callbacks.stream().filter(entry -> entry.canExecute(getUI()))
                    .forEach(entry -> {
                        ExecutionContext context = new ExecutionContext(getUI(),
                                entry.getStateNode().isClientSideInitialized());
                        entry.getExecution().accept(context);
                    });
        }
    }

private boolean hasChildAssert(StateNode child) {
        AtomicBoolean found = new AtomicBoolean(false);
        forEachChild(c -> {
            if (c == child) {
                found.set(true);
            }
        });
        return found.get();
    }

public PendingJavaScriptResult callJsFunction(String functionName,
            Serializable... arguments) {
        assert functionName != null;
        assert !functionName.startsWith(".")
                : "Function name should not start with a dot";

        // "$1,$2,$3,..."
        String paramPlaceholderString = IntStream.range(1, arguments.length + 1)
                .mapToObj(i -> "$" + i).collect(Collectors.joining(","));
        // Inject the element as $0
        Stream<Serializable> jsParameters = Stream.concat(Stream.of(this),
                Stream.of(arguments));

        return scheduleJavaScriptInvocation("return $0." + functionName + "("
                + paramPlaceholderString + ")", jsParameters);
    }

private List<StateTree.BeforeClientResponseEntry> flushCallbacks() {
        if (!hasCallbacks()) {
            return Collections.emptyList();
        }

        // Collect
        List<StateTree.BeforeClientResponseEntry> flushed = pendingExecutionNodes
                .stream().map(StateNode::dumpBeforeClientResponseEntries)
                .flatMap(List::stream)
                .sorted(BeforeClientResponseEntry.COMPARING_INDEX)
                .collect(Collectors.toList());

        // Reset bookeeping for the next round
        pendingExecutionNodes = new HashSet<>();

        return flushed;
    }

private void handleOnDetach() {
        assert isAttached();
        // Ensure detach change is sent
        markAsDirty();

        owner.unregister(this);
    }

private void setInactive(boolean inactive) {
        if (isInactiveSelf != inactive) {
            isInactiveSelf = inactive;

            visitNodeTree(child -> {
                if (!equals(child) && !child.isInactiveSelf) {
                    /*
                     * We are here if: the child node itself is not inactive but
                     * it has some ascendant which is inactive.
                     *
                     * In this case we send only some subset of changes (not
                     * from all the features). But we should send changes for
                     * all remaining features. Normally it automatically happens
                     * if the node becomes "visible". But if it was visible with
                     * some invisible parent then only the parent becomes dirty
                     * (when it's set visible) and this child will never
                     * participate in collection of changes since it's not
                     * marked as dirty.
                     *
                     * So here such node (which is active itself but its
                     * ascendant is inactive) we mark as dirty again to be able
                     * to collect its changes later on when its ascendant
                     * becomes active.
                     */
                    child.markAsDirty();
                }
            });
        }
    }

