public static boolean exportedWebComponents(JsonObject statsJson,
            ClassFinder finder) {
        try {
            Set<Class<?>> exporterRelatedClasses = new HashSet<>();
            finder.getSubTypesOf(WebComponentExporter.class.getName())
                    .forEach(exporterRelatedClasses::add);
            finder.getSubTypesOf(WebComponentExporterFactory.class.getName())
                    .forEach(exporterRelatedClasses::add);

            Set<String> webComponents = WebComponentExporterUtils
                    .getFactories(exporterRelatedClasses).stream()
                    .map(BundleValidationUtil::getTag)
                    .collect(Collectors.toSet());

            JsonArray webComponentsInStats = statsJson
                    .getArray("webComponents");

            if (webComponentsInStats == null) {
                if (!webComponents.isEmpty()) {
                    getLogger().info(
                            "Found embedded web components not yet included "
                                    + "into the bundle: {}",
                            String.join(", ", webComponents));
                    return true;
                }
                return false;
            } else {
                for (int index = 0; index < webComponentsInStats
                        .length(); index++) {
                    String webComponentInStats = webComponentsInStats
                            .getString(index);
                    webComponents.remove(webComponentInStats);
                }
            }

            if (!webComponents.isEmpty()) {
                getLogger().info(
                        "Found newly added embedded web components not "
                                + "yet included into the bundle: {}",
                        String.join(", ", webComponents));
                return true;
            }

            return false;

        } catch (ClassNotFoundException e) {
            getLogger()
                    .error("Unable to locate embedded web component classes.");
            return false;
        }
    }

FileSystem getFileSystem(URI resourceURI) throws IOException {
        synchronized (fileSystemLock) {
            URI fileURI = getFileURI(resourceURI);
            if (!fileURI.getScheme().equals("file")) {
                throw new IOException("Can not read scheme '"
                        + fileURI.getScheme() + "' for resource " + resourceURI
                        + " and will determine this as not a folder");
            }

            if (openFileSystems.computeIfPresent(fileURI,
                    (key, value) -> value + 1) != null) {
                // Get filesystem is for the file to get the correct provider
                return FileSystems.getFileSystem(resourceURI);
            }
            // Opened filesystem is for the file to get the correct provider
            FileSystem fileSystem = getNewOrExistingFileSystem(resourceURI);
            openFileSystems.put(fileURI, 1);
            return fileSystem;
        }
    }

private static void addEntryScripts(Document targetDocument,
            JsonObject statsJson) {
        boolean addIndexHtml = true;
        Element indexHtmlScript = null;
        JsonArray entryScripts = statsJson.getArray("entryScripts");
        for (int i = 0; i < entryScripts.length(); i++) {
            String entryScript = entryScripts.getString(i);
            Element elm = new Element(SCRIPT_TAG);
            elm.attr("type", "module");
            elm.attr("src", entryScript);
            targetDocument.head().appendChild(elm);

            if (entryScript.contains("indexhtml")) {
                indexHtmlScript = elm;
            }

            if (entryScript.contains("webcomponenthtml")) {
                addIndexHtml = false;
            }
        }

        // If a reference to webcomponenthtml is present, the embedded
        // components are used, thus we don't need to serve indexhtml script
        if (!addIndexHtml && indexHtmlScript != null) {
            indexHtmlScript.remove();
        }
    }

