                File frontendFolder = FrontendUtils
                        .getProjectFrontendDir(config);
                File themeFolder = getThemeFolder(frontendFolder, themeName);
                File themeJsonFile = new File(themeFolder, "theme.json");
                if (themeJsonFile.exists()) {
