private static Element getStyleTag(String themeName, String fileName,
            AbstractConfiguration config) {
        Element element;
        try {
            String themeFilePath = ThemeUtils.getThemeFilePath(themeName,
                    fileName);
            if (config.isProductionMode()) {
                element = new Element("link");
                element.attr("rel", "stylesheet");
                element.attr("type", "text/css");
                element.attr("href", themeFilePath);
            } else {
                element = new Element("style");
                element.attr("data-file-path", themeFilePath);
                File frontendDirectory = FrontendUtils
                        .getProjectFrontendDir(config);
                File stylesCss = new File(
                        ThemeUtils.getThemeFolder(frontendDirectory, themeName),
                        fileName);
                // Inline CSS into style tag to have hot module reload feature
                element.appendChild(new DataNode(CssBundler
                        .inlineImports(stylesCss.getParentFile(), stylesCss)));
            }
        } catch (IOException e) {
            throw new RuntimeException(
                    "Unable to read theme file from " + fileName, e);
        }
        return element;
    }

private static boolean checkMissedKeys(Collection<String> missedKeys,
            JsonArray arrayIterating, JsonArray arrayComparing) {
        boolean allEntriesFound = true;

        for (int arrayComparingIndex = 0; arrayComparingIndex < arrayComparing
                .length(); arrayComparingIndex++) {
            JsonValue arrayComparingEntry = arrayComparing
                    .get(arrayComparingIndex);
            boolean entryFound = false;
            for (int arrayIteratingIndex = 0; arrayIteratingIndex < arrayIterating
                    .length(); arrayIteratingIndex++) {
                JsonValue arrayIteratingEntry = arrayIterating
                        .get(arrayIteratingIndex);
                if (arrayIteratingEntry.getType() == arrayComparingEntry
                        .getType()
                        && objectIncludesEntry(arrayIteratingEntry,
                                arrayComparingEntry, missedKeys)) {
                    entryFound = true;
                    break;
                }
            }
            if (!entryFound) {
                missedKeys.add(arrayComparingEntry.toJson());
            }
            allEntriesFound = allEntriesFound && entryFound;
        }
        return allEntriesFound;
    }

