public void handleRequest(VaadinSession session, VaadinRequest request,
            VaadinResponse response, StreamResource streamResource)
            throws IOException {

        StreamResourceWriter writer;
        session.lock();
        try {
            ServletContext context = ((VaadinServletRequest) request)
                    .getServletContext();
            response.setContentType(streamResource.getContentTypeResolver()
                    .apply(streamResource, context));
            response.setCacheTime(streamResource.getCacheTime());
            streamResource.getHeaders()
                    .forEach((name, value) -> response.setHeader(name, value));
            writer = streamResource.getWriter();
            if (writer == null) {
                throw new IOException(
                        "Stream resource produces null input stream");
            }
        } catch (Exception exception) {
            response.setStatus(HttpStatusCode.INTERNAL_SERVER_ERROR.getCode());
            throw exception;

        } finally {
            session.unlock();
        }
        // don't use here "try resource" syntax sugar because in case there is
        // an exception the {@code outputStream} will be closed before "catch"
        // block which sets the status code and this code will not have any
        // effect being called after closing the stream (see #8740).
        OutputStream outputStream = null;
        try {
            outputStream = response.getOutputStream();
            writer.accept(outputStream, session);
        } catch (Exception exception) {
            response.setStatus(HttpStatusCode.INTERNAL_SERVER_ERROR.getCode());
            throw exception;
        } finally {
            if (outputStream != null) {
                outputStream.close();
            }
        }
    }

public static Optional<String> getThemeName(VaadinContext context) {
        ApplicationConfiguration config = ApplicationConfiguration.get(context);
        if (config.isProductionMode()) {
            return getThemeAnnotation(context).map(Theme::value);
        } else {
            File themeJs = new File(config.getProjectFolder(),
                    FrontendUtils.FRONTEND + FrontendUtils.GENERATED
                            + FrontendUtils.THEME_IMPORTS_NAME);

            if (!themeJs.exists()) {
                return Optional.empty();
            }

            try {
                String themeJsContent = FileUtils.readFileToString(themeJs,
                        StandardCharsets.UTF_8);
                Matcher matcher = THEME_GENERATED_FILE_PATTERN
                        .matcher(themeJsContent);
                if (matcher.find()) {
                    return Optional.of(matcher.group(1));
                } else {
                    throw new IllegalStateException(
                            "Couldn't extract theme name from theme imports file 'theme.js'");
                }
            } catch (IOException e) {
                getLogger().error(
                        "Couldn't read theme generated file to get the theme name",
                        e);
                return Optional.empty();
            }
        }
    }

