private Element createDependencyElement(BootstrapUriResolver resolver,
                LoadMode loadMode, JsonObject dependency,
                Dependency.Type type) {
            boolean inlineElement = loadMode == LoadMode.INLINE;
            String url = dependency.hasKey(Dependency.KEY_URL)
                    ? resolver.resolveVaadinUri(
                            dependency.getString(Dependency.KEY_URL))
                    : null;

            final Element dependencyElement;
            switch (type) {
            case STYLESHEET:
                dependencyElement = createStylesheetElement(url);
                break;
            case JAVASCRIPT:
                dependencyElement = createJavaScriptElement(url,
                        !inlineElement);
                break;
            case JS_MODULE:
                dependencyElement = createJavaScriptModuleElement(url, false);
                break;
            default:
                throw new IllegalStateException(
                        "Unsupported dependency type: " + type);
            }

            if (inlineElement) {
                dependencyElement.appendChild(new DataNode(
                        dependency.getString(Dependency.KEY_CONTENTS)));
            }

            return dependencyElement;
        }

private void setLocale(VaadinRequest request, VaadinSession session) {
        I18NProvider provider = getInstantiator().getI18NProvider();
        List<Locale> providedLocales = provider.getProvidedLocales();

        if (providedLocales.size() == 1) {
            session.setLocale(providedLocales.get(0));
        } else {
            Optional<Locale> foundLocale = LocaleUtil
                    .getExactLocaleMatch(request, providedLocales);

            if (!foundLocale.isPresent()) {
                foundLocale = LocaleUtil.getLocaleMatchByLanguage(request,
                        providedLocales);
            }

            // Set locale by match found in I18N provider, first provided locale
            // or else leave as default locale
            if (foundLocale.isPresent()) {
                session.setLocale(foundLocale.get());
            } else if (!providedLocales.isEmpty()) {
                session.setLocale(providedLocales.get(0));
            }
        }
    }

private static InputStream getInlineResourceStream(String url,
            ResolveContext context) {
        VaadinService service = context.getService();
        InputStream stream = service.getResourceAsStream(url);

        if (stream == null) {
            String resolvedPath = service.resolveResource(url);
            getLogger().warn("The path '{}' for inline resource "
                    + "has been resolved to '{}'. "
                    + "But resource is not available via the servlet context. "
                    + "Trying to load '{}' as a URL", url, resolvedPath, url);
            try {
                stream = new URL(url).openConnection().getInputStream();
            } catch (MalformedURLException exception) {
                throw new IllegalStateException(String.format(
                        "The path '%s' is not a valid URL. "
                                + "Unable to fetch a resource addressed by it.",
                        url), exception);
            } catch (IOException e) {
                throw new IllegalStateException(String.format(
                        COULD_NOT_READ_URL_CONTENTS_ERROR_MESSAGE, url), e);
            }
        } else if (getLogger().isDebugEnabled()) {
            String resolvedPath = service.resolveResource(url);
            getLogger().debug(
                    "The path '{}' for inline resource has been successfully "
                            + "resolved to resource URL '{}'",
                    url, resolvedPath);
        }

        return stream;
    }

