            if (context.getPushMode().isEnabled()) {
                head.appendChild(
                        createJavaScriptElement(getPushScript(context)));
            }

            head.appendChild(getBootstrapScript(initialUIDL, context));
            head.appendChild(
                    createJavaScriptElement(getClientEngineUrl(context)));
        }

