@Override
        public Document getBootstrapPage(BootstrapContext context) {
            VaadinService service = context.getSession().getService();

            try {
                Document document = Jsoup.parse(
                        FrontendUtils.getWebComponentHtmlContent(service));
                Element head = document.head();

                DeploymentConfiguration deploymentConfiguration = service
                        .getDeploymentConfiguration();

                if (deploymentConfiguration.isProductionMode()) {
                    // The web-component.html is fetched from the bundle so it
                    // includes the entry point javascripts
                } else if (!deploymentConfiguration.frontendHotdeploy()) {
                    // When running without a frontend server, the
                    // web-component.html comes
                    // directly from the frontend folder and the JS
                    // entrypoint(s) need
                    // to be added
                    addGeneratedIndexContent(deploymentConfiguration, document);
                }

                // Specify the application ID for scripts of the
                // web-component.html
                head.select("script[src]").attr("data-app-id",
                        context.getUI().getInternals().getAppId());

                // Add `crossorigin` to fix basic auth in Safari #6560
                head.select("script[src], link[href]").attr("crossorigin",
                        "true");

                JsonObject initialUIDL = getInitialUidl(context.getUI());

                head.prependChild(createInlineJavaScriptElement(
                        "window.JSCompiler_renameProperty = function(a) { return a; }"));

                head.prependChild(getBootstrapScript(initialUIDL, context));

                if (context.getPushMode().isEnabled()) {
                    head.prependChild(createJavaScriptModuleElement(
                            getPushScript(context), true));
                }

                setupCss(head, context);

                return document;
            } catch (IOException e) {
                throw new BootstrapException(
                        "Unable to read the web-component.html file.", e);
            }
        }

@Override
    public int setErrorParameter(BeforeEnterEvent event,
            ErrorParameter<NotFoundException> parameter) {
        if (getLogger().isDebugEnabled()) {
            getLogger().debug(
                    parameter.hasCustomMessage() ? parameter.getCustomMessage()
                            : "Route is not found",
                    parameter.getCaughtException());
        }
        String path = event.getLocation().getPath();
        String additionalInfo = "";
        if (parameter.hasCustomMessage()) {
            additionalInfo = "Reason: " + parameter.getCustomMessage();
        }
        path = Jsoup.clean(path, Safelist.none());
        additionalInfo = Jsoup.clean(additionalInfo, Safelist.none());

        boolean productionMode = event.getUI().getSession().getConfiguration()
                .isProductionMode();
        String template;
        String routes = getRoutes(event);

        if (productionMode) {
            template = LazyInit.PRODUCTION_MODE_TEMPLATE;
        } else if (routes.isEmpty()) {
            // The idea of showing a different error page when there are no
            // routes comes from application generated from start.spring.io, see
            // https://github.com/vaadin/flow/issues/16432
            template = readHtmlFile(EndpointRequestUtil.isHillaAvailable()
                    ? "NoRoutesError_hilla.html"
                    : "NoRoutesError_dev.html");
        } else {
            template = readHtmlFile("RouteNotFoundError_dev.html");
        }

        // {{routes}} should be replaced first so that it's not possible to
        // insert {{routes}} snippet via other template values which may result
        // in the listing of all available routes when this shouldn't happen
        if (template.contains("{{routes}}")) {
            template = template.replace("{{routes}}", routes);
        }
        template = template.replace("{{additionalInfo}}", additionalInfo);
        template = template.replace("{{path}}", path);

        getElement().setChild(0, new Html(template).getElement());
        return HttpStatusCode.NOT_FOUND.getCode();
    }

