        try {
            boolean needsBuild;
            if (mode.isProduction()) {
                if (options.isForceProductionBuild()
                        || EndpointRequestUtil.isHillaAvailable()) {
                    if (options.isForceProductionBuild()) {
                        UsageStatistics.markAsUsed("flow/prod-build-requested",
                                null);
                    }
                    getLogger().info("Frontend build requested.");
                    saveResultInFile(true, options);
                    return true;
                } else {
                    needsBuild = needsBuildProdBundle(options,
                            frontendDependencies, finder);
                    saveResultInFile(needsBuild, options);
                }
            } else if (Mode.DEVELOPMENT_BUNDLE == mode) {
                needsBuild = needsBuildDevBundle(options, frontendDependencies,
                        finder);
            } else if (Mode.DEVELOPMENT_FRONTEND_LIVERELOAD == mode) {
                return false;
            } else {
                throw new IllegalArgumentException("Unexpected mode");
            }

            if (needsBuild) {
                getLogger().info("A {} mode bundle build is needed", mode);
            } else {
                getLogger().info("A {} mode bundle build is not needed", mode);
            }
            return needsBuild;
        } catch (Exception e) {
            getLogger().error(String.format(
                    "Error when checking if a %s bundle build " + "is needed",
                    mode), e);
            return true;
        }
    }

public JsonObject createUidl(UI ui, boolean async, boolean resync) {
        JsonObject response = Json.createObject();

        UIInternals uiInternals = ui.getInternals();

        VaadinSession session = ui.getSession();
        VaadinService service = session.getService();

        // Purge pending access calls as they might produce additional changes
        // to write out
        service.runPendingAccessTasks(session);

        // Paints components
        getLogger().debug("* Creating response to client");

        if (resync) {
            response.put(ApplicationConstants.RESYNCHRONIZE_ID, true);
        }
        int nextClientToServerMessageId = uiInternals
                .getLastProcessedClientToServerId() + 1;
        response.put(ApplicationConstants.CLIENT_TO_SERVER_ID,
                nextClientToServerMessageId);

        SystemMessages messages = service.getSystemMessages(ui.getLocale(),
                null);

        JsonObject meta = new MetadataWriter().createMetadata(ui, false, async,
                messages);
        if (meta.keys().length > 0) {
            response.put("meta", meta);
        }

        JsonArray stateChanges = Json.createArray();

        encodeChanges(ui, stateChanges);

        populateDependencies(response, uiInternals.getDependencyList(),
                new ResolveContext(service, session.getBrowser()));

        if (uiInternals.getConstantPool().hasNewConstants()) {
            response.put("constants",
                    uiInternals.getConstantPool().dumpConstants());
        }
        if (stateChanges.length() != 0) {
            response.put("changes", stateChanges);
        }

        List<PendingJavaScriptInvocation> executeJavaScriptList = uiInternals
                .dumpPendingJavaScriptInvocations();
        if (!executeJavaScriptList.isEmpty()) {
            response.put(JsonConstants.UIDL_KEY_EXECUTE,
                    encodeExecuteJavaScriptList(executeJavaScriptList));
        }
        if (service.getDeploymentConfiguration().isRequestTiming()) {
            response.put("timings", createPerformanceData(ui));
        }

        // Get serverSyncId after all changes has been computed, as push may
        // have been invoked, thus incrementing the counter.
        // This way the client will receive messages in the correct order
        int syncId = service.getDeploymentConfiguration().isSyncIdCheckEnabled()
                ? uiInternals.getServerSyncId()
                : -1;
        response.put(ApplicationConstants.SERVER_SYNC_ID, syncId);
        uiInternals.incrementServerId();
        return response;
    }

public void setChildModal(Component child) {
        if (modalComponentStack == null) {
            modalComponentStack = new ArrayDeque<>();
        } else if (isTopMostModal(child)) {
            return;
        }
        ElementUtil.setIgnoreParentInert(child.getElement(), true);

        if (modalComponentStack.isEmpty()) {
            ElementUtil.setInert(ui.getElement(), true);
        } else {
            // disable previous top most modal component
            ElementUtil.setIgnoreParentInert(
                    modalComponentStack.peek().getElement(), false);
        }

        final boolean needsListener = !modalComponentStack.remove(child);
        modalComponentStack.push(child);

        if (needsListener) {
            /*
             * Handle removal automatically on element level always due to
             * possible component.getElement().removeFromParent() usage.
             */
            AtomicReference<Registration> registrationCombination = new AtomicReference<>();
            final Registration componentRemoval = () -> setChildModeless(child);
            final Registration listenerRegistration = child.getElement()
                    .addDetachListener(
                            event -> registrationCombination.get().remove());
            registrationCombination.set(Registration.combine(componentRemoval,
                    listenerRegistration));
        }
    }

