public void handleRequest(VaadinSession session, VaadinRequest request,
            VaadinResponse response, StreamResource streamResource)
            throws IOException {

        StreamResourceWriter writer;
        session.lock();
        try {
            ServletContext context = ((VaadinServletRequest) request)
                    .getServletContext();
            response.setContentType(streamResource.getContentTypeResolver()
                    .apply(streamResource, context));
            response.setCacheTime(streamResource.getCacheTime());
            streamResource.getHeaders()
                    .forEach((name, value) -> response.setHeader(name, value));
            writer = streamResource.getWriter();
            if (writer == null) {
                throw new IOException(
                        "Stream resource produces null input stream");
            }
        } catch (Exception exception) {
            response.setStatus(HttpStatusCode.INTERNAL_SERVER_ERROR.getCode());
            throw exception;

        } finally {
            session.unlock();
        }
        try (OutputStream outputStream = response.getOutputStream()) {
            try {
                writer.accept(outputStream, session);
            } catch (Exception exception) {
                // Set status before output is closed (see #8740)
                response.setStatus(
                        HttpStatusCode.INTERNAL_SERVER_ERROR.getCode());
                throw exception;
            }
        }
    }

private static boolean compareArrays(Collection<String> missedKeys,
            JsonArray jsonArrayFromBundle, JsonArray jsonArrayFromProject) {

        boolean allEntriesFound = checkMissedKeys(missedKeys,
                jsonArrayFromBundle, jsonArrayFromProject);

        // making sure that from the other jsonArray we also check and compare
        // the entries
        // to make sure both arrays have the exact same entries
        // without this it could happen that:
        // jsonArrayFromBundle = [1,2,3]
        // jsonArrayFromProject = [1,2]
        // and the check would pass
        if (jsonArrayFromBundle.length() != jsonArrayFromProject.length()) {
            allEntriesFound = allEntriesFound && checkMissedKeys(missedKeys,
                    jsonArrayFromProject, jsonArrayFromBundle);
        }

        return allEntriesFound;
    }

static Map<String, String> getReplacementsMap(String tag,
            Set<PropertyData<? extends Serializable>> propertyDataSet,
            String frontendURI, boolean generateUiImport, String themeName) {
        Map<String, String> replacements = new HashMap<>();

        if (themeName != null && !themeName.isEmpty()) {
            replacements.put("ThemeImport",
                    "import {applyTheme} from '/generated/theme';\n\n");
            replacements.put("ApplyTheme", "applyTheme(shadow);\n    ");
        } else {
            replacements.put("ThemeImport", "");
            replacements.put("ApplyTheme", "");
        }
        replacements.put("TagDash", tag);
        replacements.put("TagCamel", SharedUtil
                .capitalize(SharedUtil.dashSeparatedToCamelCase(tag)));

        replacements.put("AttributeChange", getAttributeChange(
                getStringResource(CODE_ATTRIBUTE_CHANGE), propertyDataSet));
        replacements.put("PropertyMethods", getPropertyMethods(
                getStringResource(CODE_PROPERTY_METHODS), propertyDataSet));
        replacements.put("PropertyDefaults", getPropertyDefaults(
                getStringResource(CODE_PROPERTY_DEFAULT), propertyDataSet));
        replacements.put("PropertyValues", getPropertyValues(
                getStringResource(CODE_PROPERTY_VALUES), propertyDataSet));

        replacements.put("frontend_resources", frontendURI);

        replacements.put("ui_import",
                generateUiImport
                        ? "<link rel='import' href='web-component-ui.html'>"
                        : "");

        return replacements;
    }

