private void startWatchingThemeFolder(VaadinContext context,
            ApplicationConfiguration config) {

        if (config.getMode() != Mode.DEVELOPMENT_BUNDLE) {
            // Theme files are watched by Vite or app runs in prod mode
            return;
        }

        try {
            Optional<String> maybeThemeName = ThemeUtils.getThemeName(context);

            if (maybeThemeName.isEmpty()) {
                getLogger().debug("Found no custom theme in the project. "
                        + "Skipping watching the theme files");
                return;
            }
            List<String> activeThemes = ThemeUtils.getActiveThemes(context);
            for (String themeName : activeThemes) {
                File themeFolder = ThemeUtils.getThemeFolder(
                        FrontendUtils.getProjectFrontendDir(config), themeName);
                watchers.add(new ThemeLiveUpdater(themeFolder, context));
            }
        } catch (Exception e) {
            getLogger().error("Failed to start live-reload for theme files", e);
        }
    }

private static boolean isSpecialSetter(Method method) {
        // Shorthand for Label.setFor(String)
        if (method.getDeclaringClass() == Label.class
                && method.getName().equals("setFor")
                && method.getParameterTypes()[0] == Component.class) {
            return true;
        }
        if (method.getDeclaringClass() == NativeLabel.class
                && method.getName().equals("setFor")
                && method.getParameterTypes()[0] == Component.class) {
            return true;
        }

        // Anchor.setTarget(AnchorTargetValue) -
        // https://github.com/vaadin/flow/issues/8346
        if (method.getDeclaringClass() == Anchor.class
                && method.getName().equals("setTarget")
                && method.getParameterTypes()[0] == AnchorTargetValue.class) {
            return true;
        }

        // setFoo(AbstractStreamResource) for resource URLs
        if (method.getParameterCount() == 1 && AbstractStreamResource.class
                .isAssignableFrom(method.getParameters()[0].getType())) {
            return true;
        }

        // - NativeDetails delegates it's setSummaryText to the nested <summary>
        // NativeDetails::setSummaryText(String summary)
        // - NativeDetails allows to setSummary(Component..) but it returns
        // Summary getSummary instead of Component[]
        // NativeDetails::setSummary(Component... components)
        if (method.getDeclaringClass() == NativeDetails.class
                && method.getName().startsWith("setSummary")) {
            return true;
        }

        return false;
    }

static JsonObject loadStatsJson() {
        URL statsUrl = BundleUtils.class.getClassLoader()
                .getResource("META-INF/VAADIN/config/stats.json");
        if (statsUrl == null) {
            return Json.createObject();
        }
        try {
            return Json
                    .parse(IOUtils.toString(statsUrl, StandardCharsets.UTF_8));
        } catch (IOException e) {
            getLogger().warn(
                    "Unable to parse META-INF/VAADIN/config/stats.json", e);
            return Json.createObject();
        }
    }

private void addInitialFlow(JsonObject initialJson, Document indexDocument,
            VaadinRequest request) {
        SpringCsrfTokenUtil.addTokenAsMetaTagsToHeadIfPresentInRequest(
                indexDocument.head(), request);
