public void autoSwitch(WebSession session, UserDTO user) {
        // 用户有 last_project_id 权限
        if (hasLastProjectPermission(user)) {
            return;
        }
        // 用户有 last_workspace_id 权限
        if (hasLastWorkspacePermission(user)) {
