        if (this instanceof Component) {
            return ComponentUtil.addListener((Component) this, ClickEvent.class,
                    (ComponentEventListener) listener,
                    d -> d.setFilter("event.detail == 2"));
        } else {
            throw new IllegalStateException(String.format(
