private List<String> getDependencyTriggers(Class<?> route,
            Class triggerClass) {
        try {
            Annotation triggerAnnotation = route.getAnnotation(triggerClass);
            if (triggerAnnotation != null) {
                Method valueMethod = triggerClass.getMethod("value");
                Class<?> triggers[] = (Class<?>[]) valueMethod
                        .invoke(triggerAnnotation);
                if (triggers != null) {
                    return Stream.of(triggers).map(cls -> cls.getName())
                            .toList();
                }
            }

        } catch (SecurityException | IllegalArgumentException
                | IllegalAccessException | NoSuchMethodException
                | InvocationTargetException e) {
            log().warn(
                    "Unable to determine load mode for route class {}. Using eager.",
                    route.getName(), e);
        }
        return null;
    }

@Override
    public String getRoutePath(Class<?> navigationTarget) {
        Route route = navigationTarget.getAnnotation(Route.class);
        if (route == null) {
            return null;
        }

        if (route.value().equals(Route.NAMING_CONVENTION)) {
            String simpleName = navigationTarget.getSimpleName();
            if ("MainView".equals(simpleName) || "Main".equals(simpleName)) {
                return "";
            }
            if (simpleName.endsWith("View")) {
                return simpleName
                        .substring(0, simpleName.length() - "View".length())
                        .toLowerCase();
            }
            return simpleName.toLowerCase();
        }
        return route.value();

    }

