private Map<File, List<String>> process(Map<ChunkInfo, List<CssData>> css,
            Map<ChunkInfo, List<String>> javascript) {
        Map<File, List<String>> files = new HashMap<>();

        Map<ChunkInfo, List<String>> lazyJavascript = new LinkedHashMap<>();
        List<String> eagerJavascript = new ArrayList<>();
        Map<ChunkInfo, List<String>> lazyCss = new LinkedHashMap<>();
        List<CssData> eagerCssData = new ArrayList<>();
        for (Entry<ChunkInfo, List<String>> entry : javascript.entrySet()) {
            if (isLazyRoute(entry.getKey())) {
                lazyJavascript.put(entry.getKey(), entry.getValue());
            } else {
                eagerJavascript.addAll(entry.getValue());
            }
        }

        for (Entry<ChunkInfo, List<CssData>> entry : css.entrySet()) {
            if (isLazyRoute(entry.getKey())) {
                List<String> cssLines = getCssLines(entry.getValue());
                if (!cssLines.isEmpty()) {
                    lazyCss.put(entry.getKey(), cssLines);
                }
            } else {
                eagerCssData.addAll(entry.getValue());
            }
        }

        List<String> chunkLoader = new ArrayList<>();
        if (!lazyJavascript.isEmpty() || !lazyCss.isEmpty()) {
            chunkLoader.add("");
            chunkLoader.add("const loadOnDemand = (key) => {");
            chunkLoader.add("  const pending = [];");
            for (ChunkInfo chunkInfo : merge(lazyJavascript.keySet(),
                    lazyCss.keySet())) {
                String routeHash = BundleUtils.getChunkId(chunkInfo.getName());
                String chunkFilename = "chunk-" + routeHash + ".js";

                String ifClauses = chunkInfo.getDependencyTriggers().stream()
                        .map(cls -> BundleUtils.getChunkId(cls))
                        .map(hash -> "key === '" + hash + "'")
                        .collect(Collectors.joining(" || "));
                chunkLoader.add("  if (" + ifClauses + ") {");
                chunkLoader.add("    pending.push(import('./chunks/"
                        + chunkFilename + "'));");
                chunkLoader.add("  }");

                List<String> chunkLines = new ArrayList<>();
                if (lazyJavascript.containsKey(chunkInfo)) {
                    chunkLines
                            .addAll(getModuleLines(javascript.get(chunkInfo)));
                }
                if (lazyCss.containsKey(chunkInfo)) {
                    chunkLines.add(IMPORT_INJECT);
                    chunkLines.add(THEMABLE_MIXIN_IMPORT);
                    chunkLines.addAll(lazyCss.get(chunkInfo));
                }
                File chunkFile = new File(chunkFolder, chunkFilename);
                files.put(chunkFile, chunkLines);
            }

            chunkLoader.add("  return Promise.all(pending);");
            chunkLoader.add("}");
            chunkLoader.add("");
        } else {
            chunkLoader.add(
                    "const loadOnDemand = (key) => { return Promise.resolve(0); }");
        }

        List<String> mainLines = new ArrayList<>();

        // Convert eager CSS data to JS and deduplicate it
        List<String> mainCssLines = getCssLines(eagerCssData);
        if (!mainCssLines.isEmpty()) {
            mainLines.add(IMPORT_INJECT);
            mainLines.add(THEMABLE_MIXIN_IMPORT);
            mainLines.addAll(mainCssLines);
        }
        mainLines.addAll(getModuleLines(eagerJavascript));
        mainLines.addAll(chunkLoader);
        mainLines.add("window.Vaadin = window.Vaadin || {};");
        mainLines.add("window.Vaadin.Flow = window.Vaadin.Flow || {};");
        mainLines.add("window.Vaadin.Flow.loadOnDemand = loadOnDemand;");

        files.put(generatedFlowImports, mainLines);
        files.put(generatedFlowDefinitions,
                Collections.singletonList("export {}"));

        return files;
    }

@Test
    public void generateLines_resultingLinesContainsThemeLinesAndExpectedImportsAndCssLinesAndGeneratedImportsAndLoggerReports()
            throws Exception {
        List<String> expectedLines = new ArrayList<>();
        getExpectedImports().stream().filter(imp -> imp.equals("/foo.css"))
                .forEach(imp -> expectedLines
                        .add("import '" + addWebpackPrefix(imp) + "';"));

        // An import without `.js` extension
        expectedLines.add(
                "import '@vaadin/vaadin-mixed-component/theme/lumo/vaadin-something-else';");
        // An import not found in node_modules
        expectedLines.add("import 'unresolved/component';");

        expectedLines.add(
                "import $cssFromFile_0 from '@vaadin/vaadin-mixed-component/bar.css?inline';");
        expectedLines
                .add("import $cssFromFile_1 from 'Frontend/foo.css?inline';");
        expectedLines
                .add("import $cssFromFile_2 from 'Frontend/foo.css?inline';");
        expectedLines
                .add("import $cssFromFile_3 from 'Frontend/foo.css?inline';");
        expectedLines
                .add("import $cssFromFile_4 from 'Frontend/foo.css?inline';");
        expectedLines
                .add("import $cssFromFile_5 from 'Frontend/foo.css?inline';");
        expectedLines
                .add("import $cssFromFile_6 from 'Frontend/foo.css?inline';");
        expectedLines.add(
                "injectGlobalCss($cssFromFile_0.toString(), 'CSSImport end', document);");
        expectedLines.add(
                "injectGlobalCss($cssFromFile_1.toString(), 'CSSImport end', document);");
        expectedLines.add(
                "addCssBlock(`<style include=\"bar\">${$css_2}</style>`);");
        expectedLines.add("registerStyles('', $css_3, {moduleId: 'baz'});");
        expectedLines.add(
                "registerStyles('', $css_4, {include: 'bar', moduleId: 'baz'});");
        expectedLines.add(
                "registerStyles('foo-bar', $css_5, {moduleId: 'flow_css_mod_5'});");
        expectedLines.add(
                "registerStyles('foo-bar', $css_6, {include: 'bar', moduleId: 'flow_css_mod_6'});");

        expectedLines
                .add("import 'Frontend/generated/flow/generated-modules-foo';");
        expectedLines
                .add("import 'Frontend/generated/flow/generated-modules-bar';");

        updater.run();

        for (String line : expectedLines) {
            Assert.assertTrue(
                    "\n" + line + " IS NOT FOUND IN: \n"
                            + updater.resultingLines,
                    updater.resultingLines.contains(line));
        }

        // All generated module ids are distinct
        Pattern moduleIdPattern = Pattern
                .compile(".*moduleId: '(flow_css_mod_[^']*)'.*");
        List<String> moduleIds = updater.resultingLines.stream()
                .map(moduleIdPattern::matcher).filter(Matcher::matches)
                .map(m -> m.group(1)).collect(Collectors.toList());
        long uniqueModuleIds = moduleIds.stream().distinct().count();
        Assert.assertTrue("expected modules", moduleIds.size() > 0);
        Assert.assertEquals("duplicates in generated " + moduleIds,
                moduleIds.size(), uniqueModuleIds);

        String output = logger.getLogs();

        MatcherAssert.assertThat(output, CoreMatchers.containsString(
                "Use the './' prefix for files in JAR files: 'ExampleConnector.js'"));
        MatcherAssert.assertThat(output, CoreMatchers
                .containsString("Use the './' prefix for files in the '"
                        + frontendDirectory.getPath()
                        + "' folder: 'vaadin-mixed-component/theme/lumo/vaadin-mixed-component.js'"));

        // Using regex match because of the ➜ character in TC
        MatcherAssert.assertThat(output, CoreMatchers.containsString(
                "Failed to find the following imports in the `node_modules` tree:\n      - unresolved/component"));

        MatcherAssert.assertThat(output,
                CoreMatchers.not(CoreMatchers.containsString(
                        "changing 'frontend://foo-dir/javascript-lib.js' to './foo-dir/javascript-lib.js'")));
    }

private ChunkInfo getChunkInfo(EntryPointData data) {
        if (data.getType() == EntryPointType.INTERNAL) {
            return ChunkInfo.GLOBAL;
        }
        return new ChunkInfo(data.getType(), data.getName(),
                data.getDependencyTriggers(), data.isEager());
    }

