boolean lockVersionForNpm(JsonObject packageJson) throws IOException {
        if (enablePnpm) {
            return false;
        }
        boolean versionLockingUpdated = false;

        JsonObject overridesSection = getOverridesSection(packageJson);
        final JsonObject dependencies = packageJson.getObject(DEPENDENCIES);
        for (String dependency : versionsJson.keys()) {
            if (!overridesSection.hasKey(dependency)
                    && shouldLockDependencyVersion(dependency, dependencies,
                            versionsJson)) {
                overridesSection.put(dependency, "$" + dependency);
                versionLockingUpdated = true;
            }
        }
        final JsonObject devDependencies = packageJson
                .getObject(DEV_DEPENDENCIES);
        for (String dependency : overridesSection.keys()) {
            if (!dependencies.hasKey(dependency)
                    && !devDependencies.hasKey(dependency)
                    && overridesSection.getString(dependency).startsWith("$")) {
                overridesSection.remove(dependency);
                versionLockingUpdated = true;
            }
        }

        return versionLockingUpdated;
    }

boolean updateDefaultDependencies(JsonObject packageJson) {
        int added = 0;

        for (Map.Entry<String, String> entry : getDefaultDependencies()
                .entrySet()) {
            added += addDependency(packageJson, DEPENDENCIES, entry.getKey(),
                    entry.getValue());
        }

        for (Map.Entry<String, String> entry : getDefaultDevDependencies()
                .entrySet()) {
            added += addDependency(packageJson, DEV_DEPENDENCIES,
                    entry.getKey(), entry.getValue());
        }

        if (added > 0) {
            log().debug("Added {} default dependencies to main package.json",
                    added);
        }
        return added > 0;
    }

protected static FrontendVersion getVersion(String tool,
            List<String> versionCommand) throws UnknownVersionException {
        String output;
        try {
            output = executeCommand(versionCommand);
        } catch (CommandExecutionException e) {
            throw new UnknownVersionException(tool,
                    "Using command " + String.join(" ", versionCommand), e);
        }

        try {
            return new FrontendVersion(parseVersionString(output));
        } catch (IOException e) {
            throw new UnknownVersionException(tool,
                    "Expected a version number as output but got '" + output
                            + "'" + " when using command "
                            + String.join(" ", versionCommand),
                    e);
        }
    }

private void collectExporterEntrypoints(Class<?> clazz)
            throws ClassNotFoundException {
        // Because of different classLoaders we need compare against class
        // references loaded by the specific class finder loader
        Class<? extends Annotation> routeClass = getFinder()
                .loadClass(Route.class.getName());
        Class<?> exporterClass = getFinder().loadClass(clazz.getName());
        Set<? extends Class<?>> exporterClasses = getFinder()
                .getSubTypesOf(exporterClass);

        // if no exporters in the project, return
        if (exporterClasses.isEmpty()) {
            return;
        }

        HashMap<String, EntryPointData> exportedPoints = new HashMap<>();

        for (Class<?> exporter : exporterClasses) {
            String exporterClassName = exporter.getName();
            if (!entryPoints.containsKey(exporterClassName)) {
                addEntryPoint(exporter, EntryPointType.WEB_COMPONENT, null,
                        true);
            }

            if (!Modifier.isAbstract(exporter.getModifiers())) {
                Class<? extends Component> componentClass = (Class<? extends Component>) ReflectTools
                        .getGenericInterfaceType(exporter, exporterClass);
                if (componentClass != null
                        && !componentClass.isAnnotationPresent(routeClass)) {
                    addEntryPoint(componentClass, EntryPointType.WEB_COMPONENT,
                            null, true);
                }
            }
        }

        entryPoints.putAll(exportedPoints);
    }

