            // Strip line-feed and new-line characters if present.
            title = title.replaceAll("[\n\r]", "");
            // Truncate long titles.
            // TODO: the value should be asked to the store API instead of being hardcoded
            if (title.length() > 768) {
                title = title.substring(0, 768);
            }
        }
        return title;
    }

@Override
    public XDOMOfficeDocument build(InputStream officeFileStream, String officeFileName,
        DocumentReference documentReference) throws OfficeImporterException
    {
        // Invoke the office document converter.
        OfficeConverterResult officeConverterResult = importPresentation(officeFileStream, officeFileName);

        Pair<String, Map<String, OfficeDocumentArtifact>> htmlPresentationResult;
        // Create presentation HTML.
        try {
            htmlPresentationResult = buildPresentationHTML(officeConverterResult,
                StringUtils.substringBeforeLast(officeFileName, "."));
        } catch (IOException e) {
            throw new OfficeImporterException("Error while preparing the presentation artifacts.", e);
        }

        // Clear and adjust presentation HTML (slide image URLs are updated to point to the corresponding attachments).
        String html = cleanPresentationHTML(htmlPresentationResult.getLeft(), documentReference);

        // Create the XDOM.
        XDOM xdom = buildPresentationXDOM(html, documentReference);

        return new XDOMOfficeDocument(xdom, htmlPresentationResult.getRight(),
            this.contextComponentManagerProvider.get(), officeConverterResult);
    }

private XDOMOfficeDocument createXDOM(DocumentReference ownerDocument, InputStream officeFileStream,
        String officeFileName, Map<String, ?> parameters) throws Exception
    {
        try {
            if (isPresentation(officeFileName)) {
                return this.presentationBuilder.build(officeFileStream, officeFileName, ownerDocument);
            } else {
                boolean filterStyles = this.converter.convert(boolean.class, parameters.get("filterStyles"));
                return this.documentBuilder.build(officeFileStream, officeFileName, ownerDocument, filterStyles);
            }
        } finally {
            IOUtils.closeQuietly(officeFileStream);
        }
    }

@Override
    public void initialize() throws InitializationException
    {
        try {
            LRUCacheConfiguration attachmentConfig = new LRUCacheConfiguration(MODULE_NAME + ".attachment", 50);
            this.attachmentCache = this.cacheManager.createNewCache(attachmentConfig);

            // We have no idea when to invalidate the cache so lets at least put a time to live
            LRUCacheConfiguration exteralConfig = new LRUCacheConfiguration(MODULE_NAME + ".external", 50, 3600);
            this.externalCache = this.cacheManager.createNewCache(exteralConfig);
        } catch (CacheException e) {
            throw new InitializationException("Failed to create caches.", e);
        }
    }

private String getFileName(Attr source, String replacePrefix, String replacementPrefix) throws MimeTypeException
    {
        String value = source.getValue();
        String fileName = null;
        @SuppressWarnings("unchecked")
        Map<String, byte[]> embeddedImages =
            (Map<String, byte[]>) source.getOwnerDocument().getUserData(EMBEDDED_IMAGES);
        if (embeddedImages != null && value.startsWith("data:")) {
            // An image embedded using the Data URI scheme.
            DataUri dataURI = DataUri.parse(value, Charset.forName(UTF_8));
            fileName = dataURI.getFilename();
            if (StringUtils.isEmpty(fileName)) {
                fileName = String.valueOf(Math.abs(dataURI.hashCode()));
                if (!StringUtils.isEmpty(dataURI.getMime())) {
                    String extension = MimeTypes.getDefaultMimeTypes().forName(dataURI.getMime()).getExtension();
                    fileName += extension;
                }
            }
            embeddedImages.put(fileName, dataURI.getData());
        } else if (!value.contains("://")) {
            // A relative path.
            int separator = value.lastIndexOf('/');
            fileName = separator < 0 ? value : value.substring(separator + 1);
            try {

                /*
                We need to manage here several special cases because of both jodconverter/libreoffice behaviour
                when processing image URL and HtmlCleaner when processing XML attributes.
                First of all, jodconverter/libreoffice does not currently process well the "+" character: it does not
                encode it when creating the URL which might lead to an error when decoding the URL. An issue has been
                opened there: https://github.com/sbraconnier/jodconverter/issues/125

                Then HtmlCleaner escape all characters it finds in Html attribute which lead to an error when it
                concerns "&" character.
                Finally '@' is used in XWiki Syntax so it needs to be escaped to build the link properly.
                 */
                fileName = fileName.replaceAll("\\+", "%2B");
                // We have to decode the image file name in case it contains URL special characters.
                fileName = URLDecoder.decode(fileName, UTF_8);
            } catch (Exception e) {
                // This shouldn't happen. Use the encoded image file name.
            }

            fileName = replacePrefix(replacePrefix, replacementPrefix, fileName);
            // '@' must also be escaped in order to resolve properly the path in XWiki
            fileName = fileName.replace("@", "\\@");
        }
        return fileName;
    }

protected OfficeConverterResult importPresentation(InputStream officeFileStream, String officeFileName)
        throws OfficeImporterException
    {
        Map<String, InputStream> inputStreams = new HashMap<String, InputStream>();
        inputStreams.put(officeFileName, officeFileStream);
        try {
            // The office converter uses the output file name extension to determine the output format/syntax.
            // The returned artifacts are of three types: imgX.jpg (slide screen shot), imgX.html (HTML page that
            // display the corresponding slide screen shot) and textX.html (HTML page that display the text extracted
            // from the corresponding slide). We use "img0.html" as the output file name because the corresponding
            // artifact displays a screen shot of the first presentation slide.
            return this.officeServer.getConverter().convertDocument(inputStreams, officeFileName, "img0.html");
        } catch (OfficeConverterException e) {
            String message = "Error while converting document [%s] into html.";
            throw new OfficeImporterException(String.format(message, officeFileName), e);
        }
    }

