@Override
    public <T> List<T> search(final String sql, int nb, int start, Object[][] whereParams, List<?> parameterValues,
        XWikiContext inputxcontext) throws XWikiException
    {
        if (sql == null) {
            return null;
        }

        return executeRead(inputxcontext, session -> {
            try {
                boolean legacyOrdinal = LegacySessionImplementor.containsLegacyOrdinalStatement(sql);

                String statement = sql;

                if (whereParams != null) {
                    statement += generateWhereStatement(whereParams,
                        legacyOrdinal ? -1 : CollectionUtils.size(parameterValues.size()));
                }

                statement = filterSQL(statement);
                Query<T> query = session.createQuery(statement);

                injectParameterListToQuery(legacyOrdinal ? 0 : 1, query, parameterValues);

                if (whereParams != null) {
                    int parameterIndex = CollectionUtils.size(parameterValues);
                    if (legacyOrdinal) {
                        ++parameterIndex;
                    }
                    for (Object[] whereParam : whereParams) {
                        query.setParameter(parameterIndex++, whereParam[1]);
                    }
                }

                if (start > 0) {
                    query.setFirstResult(start);
                }
                if (nb > 0) {
                    query.setMaxResults(nb);
                }
                List<T> list = new ArrayList<>();
                list.addAll(query.list());

                return list;
            } catch (Exception e) {
                Object[] args = {sql};
                throw new XWikiException(XWikiException.MODULE_XWIKI_STORE,
                    XWikiException.ERROR_XWIKI_STORE_HIBERNATE_SEARCH,
                    "Exception while searching documents with sql {0}", e, args);
            }
        });
    }

private void injectParameterToQuery(int parameterId, Query<?> query, Object parameterValue)
    {
        query.setParameter(parameterId, parameterValue);
    }

@Override
    protected XDOM extractTitleFromContent(DocumentModelBridge document, DocumentDisplayerParameters parameters)
    {
        // Note: Ideally we should apply transformations on the document's returned XDOM here since macros could
        // generate headings for example or some other transformations could modify headings. However we don't do this
        // at the moment since it would be too costly to do so. In the future we will even probably remove the feature
        // of generating the title from the content.
        List<HeaderBlock> blocks =
            document.getXDOM().getBlocks(new ClassBlockMatcher(HeaderBlock.class), Block.Axes.DESCENDANT);
        if (!blocks.isEmpty()) {
            HeaderBlock heading = blocks.get(0);
            // Check the heading depth after which we should return null if no heading was found.
            if (heading.getLevel().getAsInt() <= displayConfiguration.getTitleHeadingDepth()) {
                XDOM headingXDOM = new XDOM(Collections.<Block> singletonList(heading));
                try {
                    TransformationContext txContext =
                        new TransformationContext(headingXDOM, document.getSyntax(),
                            parameters.isTransformationContextRestricted() || document.isRestricted());
                    txContext.setTargetSyntax(parameters.getTargetSyntax());
                    transformationManager.performTransformations(headingXDOM, txContext);

                    Block headingBlock = headingXDOM.getChildren().size() > 0 ? headingXDOM.getChildren().get(0) : null;
                    if (headingBlock instanceof HeaderBlock) {
                        return new XDOM(headingBlock.getChildren());
                    }
                } catch (TransformationException e) {
                    getLogger().warn("Failed to extract title from document content.");
                }
            }
        }
        return null;
    }

private List<Block> executeContext(XDOM xdom, ContextMacroParameters parameters, MacroTransformationContext context)
        throws MacroExecutionException
    {
        DocumentReference referencedDocReference;
        if (parameters.getDocument() != null) {
            referencedDocReference =
                this.macroReferenceResolver.resolve(parameters.getDocument(), context.getCurrentMacroBlock());
            DocumentReference currentAuthor = this.documentAccessBridge.getCurrentAuthorReference();

            // Make sure the author is allowed to use the target document
            checkAccess(currentAuthor, referencedDocReference);
        } else {
            referencedDocReference = null;
        }

        // Reuse the very generic async rendering framework (even if we don't do async and caching) since it's
        // taking
        // care of many other things
        BlockAsyncRendererConfiguration configuration = createBlockAsyncRendererConfiguration(null, xdom, context);
        configuration.setAsyncAllowed(false);
        configuration.setCacheAllowed(false);

        if (parameters.isRestricted()) {
            configuration.setResricted(true);
        }

        Map<String, Object> backupObjects = null;
        try {
            if (referencedDocReference != null) {
                backupObjects = new HashMap<>();

                // Switch the context document
                this.documentAccessBridge.pushDocumentInContext(backupObjects, referencedDocReference);

                // Apply the transformations but with a Transformation Context having the XDOM of the passed
                // document so that macros execute on the passed document's XDOM (e.g. the TOC macro will generate
                // the toc for the passed document instead of the current document).
                DocumentModelBridge referencedDoc =
                    this.documentAccessBridge.getTranslatedDocumentInstance(referencedDocReference);
                XDOM referencedXDOM = referencedDoc.getXDOM();

                if (parameters.getTransformationContext() == TransformationContextMode.TRANSFORMATIONS) {
                    // Get the XDOM from the referenced doc but with Transformations applied so that all macro are
                    // executed and contribute XDOM elements.
                    // IMPORTANT: This can be dangerous since it means executing macros, and thus also script macros
                    // defined in the referenced document. To be used with caution.
                    TransformationContext referencedTxContext =
                        new TransformationContext(referencedXDOM, referencedDoc.getSyntax(),
                            referencedDoc.isRestricted());
                    this.transformationManager.performTransformations(referencedXDOM, referencedTxContext);
                }

                // Configure the Transformation Context XDOM depending on the mode asked.
                configuration.setXDOM(referencedXDOM);
            }

            // Execute the content
            Block result = this.executor.execute(configuration);

            return result.getChildren();
        } catch (Exception e) {
            throw new MacroExecutionException("Failed start the execution of the macro", e);
        } finally {
            if (backupObjects != null) {
                // Restore the context document
                this.documentAccessBridge.popDocumentFromContext(backupObjects);
            }
        }
    }

