        this.document.setRestricted(true);
        this.document.setContent(content);
        this.oldcore.getXWikiContext().setDoc(null);

        // Verify that the Velocity macro is not executed.
        assertThat(this.document.getRenderedContent(this.oldcore.getXWikiContext()),
            startsWith("<div class=\"xwikirenderingerror\">Failed to execute the [velocity] macro."));

        this.document.setRestricted(false);

        assertEquals("<p>test</p>", this.document.getRenderedContent(this.oldcore.getXWikiContext()));

        this.oldcore.getXWikiContext().setDoc(otherDocument);

        assertEquals("<p>test</p>", apiDocument.getRenderedContent(content, Syntax.XWIKI_2_1.toIdString()));

        otherDocument.setRestricted(true);

        assertThat(apiDocument.getRenderedContent(content, Syntax.XWIKI_2_1.toIdString()),
            startsWith("<div class=\"xwikirenderingerror\">Failed to execute the [velocity] macro."));

        this.oldcore.getXWikiContext().put("sdoc", sdoc);
        assertEquals("<p>test</p>", apiDocument.getRenderedContent(content, Syntax.XWIKI_2_1.toIdString()));

        sdoc.setRestricted(true);

        assertThat(apiDocument.getRenderedContent(content, Syntax.XWIKI_2_1.toIdString()),
            startsWith("<div class=\"xwikirenderingerror\">Failed to execute the [velocity] macro."));
    }

private void updateXWikiSpaceTable(XWikiDocument document, Session session)
    {
        if (document.getLocale().equals(Locale.ROOT)) {
            // It's possible the space does not yet exist yet
            maybeCreateSpace(document.getDocumentReference().getLastSpaceReference(), document.isHidden(), session);

            if (!document.isNew()) {
                // If the hidden state of an existing document did not changed there is nothing to do
                if (document.isHidden() != document.getOriginalDocument().isHidden()) {
                    if (document.isHidden()) {
                        // If the document became hidden it's possible the space did too
                        maybeMakeSpaceHidden(document.getDocumentReference().getLastSpaceReference(),
                            document.getFullName(), session);
                    } else {
                        // If the document became visible then all its parents should be visible as well
                        makeSpaceVisible(document.getDocumentReference().getLastSpaceReference(), session);
                    }
                }
            }
        }
    }

