private void releaseWriteLock(String id) {
        Semaphore lock = locks.get(id);
        // while semaphores are thread safe by nature,
        // the if-condition below isn't
        synchronized (lock) {
            if (lock.availablePermits() < 1) {
                // we never give more than one permit
                lock.release();
            }
        }
    }

