public static void dbConfig(
            List<DBConfig> configs, String name, String driver, String connectionUrl) {
        try {
            Class.forName(driver);
        } catch (ClassNotFoundException cnfe) {
            System.err.println("skipping " + name + " tests, enable via maven profile");
            return;
        }
        if ("true"
                .equals(
                        System.getProperty(
                                "jdbcconfig." + name + ".skip",
                                "h2".equals(name) ? "false" : "true"))) {
            System.err.println("skipping " + name + " tests, enable via maven profile");
            return;
        }
        DBConfig conf = new DBConfig();
        conf.name = name;
        conf.driver = driver;
        conf.connectionUrl = connectionUrl;
        conf.dbUser = System.getProperty("user.name");
        conf.dbPasswd = "";

        connectionUrl = getProperty(name, "connectionUrl");
        if (connectionUrl != null) {
            conf.connectionUrl = connectionUrl;
        }
        String dbUser = getProperty(name, "dbUser");
        if (dbUser != null) {
            conf.dbUser = dbUser;
        }
        String dbPass = getProperty(name, "dbPasswd");
        if (dbPass != null) {
            conf.dbPasswd = dbPass;
        }
        try {
            conf.dataSource();
        } catch (Exception ex) {
            System.err.println(
                    "Unable to connect to datastore, either disable test or specify correct configuration:");
            System.out.println(ex.getMessage());
            System.out.println("Current configuration : " + conf.detailString());
            return;
        }
        configs.add(conf);
    }

public <T extends CatalogInfo> int count(final Class<T> of, final Filter filter) {

        QueryBuilder<T> sqlBuilder = QueryBuilder.forCount(dialect, of, dbMappings).filter(filter);

        final String sql = sqlBuilder.build();
        final Filter unsupportedFilter = sqlBuilder.getUnsupportedFilter();
        final boolean fullySupported = Filter.INCLUDE.equals(unsupportedFilter);
        if (LOGGER.isLoggable(Level.FINER)) {
            LOGGER.finer("Original filter: " + filter);
            LOGGER.finer("Supported filter: " + sqlBuilder.getSupportedFilter());
            LOGGER.finer("Unsupported filter: " + sqlBuilder.getUnsupportedFilter());
        }
        final int count;
        if (fullySupported) {
            final Map<String, Object> namedParameters = sqlBuilder.getNamedParameters();
            logStatement(sql, namedParameters);

            count = template.queryForObject(sql, namedParameters, Integer.class);
        } else {
            LOGGER.fine(
                    "Filter is not fully supported, doing scan of supported part to return the number of matches");
            // going the expensive route, filtering as much as possible
            CloseableIterator<T> iterator = query(of, filter, null, null, (SortBy) null);
            try {
                return Iterators.size(iterator);
            } finally {
                iterator.close();
            }
        }
        return count;
    }

