protected boolean isGeodeticSrid(Integer srid, Connection cx) {
        if (srid == null) return false;

        Boolean geodetic = geodeticCache.get(srid);

        if (geodetic == null) {
            synchronized (this) {
                geodetic = geodeticCache.get(srid);

                if (geodetic == null) {
                    PreparedStatement ps = null;
                    ResultSet rs = null;
                    boolean closeConnection = false;
                    try {
                        ps =
                                cx.prepareStatement(
                                        "SELECT COUNT(*) FROM MDSYS.GEODETIC_SRIDS WHERE SRID = ?");
                        ps.setInt(1, srid);
                        rs = ps.executeQuery();
                        rs.next();
                        geodetic = rs.getInt(1) > 0;
                        geodeticCache.put(srid, geodetic);
                    } catch (SQLException e) {
                        LOGGER.log(
                                Level.WARNING,
                                "Could not evaluate if the SRID " + srid + " is geodetic",
                                e);
                    } finally {
                        dataStore.closeSafe(rs);
                        dataStore.closeSafe(ps);
                        if (closeConnection) dataStore.closeSafe(cx);
                    }
                }
            }
        }

        return geodetic != null ? geodetic : false;
    }

org.opengis.filter.Filter compare(
            Class filterType,
            org.opengis.filter.expression.Expression a,
            org.opengis.filter.expression.Expression b) {
        if (filterType == PropertyIsLessThan.class) {
            return fac.less(a, b);
        } else if (filterType == PropertyIsLessThanOrEqualTo.class) {
            return fac.lessOrEqual(a, b);
        }
        if (filterType == PropertyIsEqualTo.class) {
            return fac.equals(a, b);
        } else if (filterType == PropertyIsGreaterThanOrEqualTo.class) {
            return fac.greaterOrEqual(a, b);
        } else if (filterType == PropertyIsGreaterThan.class) {
            return fac.greater(a, b);
        } else {
            throw new IllegalArgumentException("Uknown compare filter type " + filterType);
        }
    }

