private Class readGeometryClassFromStatement(Connection cx, String sql, List<String> parameters)
            throws SQLException {
        PreparedStatement st = null;
        ResultSet rs = null;
        try {
            LOGGER.log(
                    Level.FINE,
                    "Geometry type check; {0} [ parameters = {1} ]",
                    new Object[] {sql, parameters});
            st = cx.prepareStatement(sql);
            for (int i = 0; i < parameters.size(); i++) {
                st.setString(i + 1, parameters.get(i));
            }
            rs = st.executeQuery();
            if (rs.next()) {
                String gType = rs.getString(1);
                Class geometryClass = TT.GEOM_CLASSES.get(gType);
                if (geometryClass == null) {
                    // if there was a record but it's not a recognized geometry type fall back on
                    // geometry for backwards compatibility, but at least log the info
                    LOGGER.fine(
                            "Unrecognized geometry type "
                                    + gType
                                    + " falling back on generic 'GEOMETRY'");
                    geometryClass = Geometry.class;
                }

                return geometryClass;
            }
        } finally {
            dataStore.closeSafe(rs);
            dataStore.closeSafe(st);
        }

        return null;
    }

public Object visitSupportedEqualFunction(
            PropertyIsEqualTo filter,
            SQLDialect dialect,
            BiConsumer<Geometry, StringBuffer> encodeGeometryValue,
            Object extraData) {
        FilterFunction_pgNearest nearest = getNearestFilter(filter);
        InArrayFunction inArray = getInArray(filter);
        FilterFunction_equalTo equalTo = getEqualTo(filter);
        if (nearest != null) {
            return visit(
                    nearest, extraData, new NearestHelperContext(dialect, encodeGeometryValue));
        } else if (inArray != null) {
            return visit(inArray, extraData);
        } else if (equalTo != null) {
            return visit(equalTo, extraData);
        }
        return null;
    }

