protected void visitInFunction(
            Function function, boolean encodeAsExpression, boolean negate, Object extraData) {
        try {
            if (encodeAsExpression) {
                out.write("(");
            }

            // figure out the context, the first property name found will be used as a type
            // reference,
            // otherwise null context will be used
            List<Expression> parameters = function.getParameters();
            Class context =
                    function.getParameters().stream()
                            .filter(p -> p instanceof PropertyName)
                            .map(p -> p.evaluate(featureType))
                            .filter(o -> o instanceof AttributeDescriptor)
                            .map(o -> ((AttributeDescriptor) o).getType().getBinding())
                            .findFirst()
                            .orElse(null);

            // encode the attribute being tested, as is
            function.getParameters().get(0).accept(this, context);

            if (negate) {
                out.write(" NOT IN (");
            } else {
                out.write(" IN (");
            }

            // encode all other values to be used
            int size = parameters.size();
            for (int i = 1; i < size; i++) {
                Expression e = function.getParameters().get(i);
                e.accept(this, context);

                if (i < size - 1) {
                    out.write(", ");
                }
            }
            out.write(")");

            if (encodeAsExpression) {
                out.write(")");
            }
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

public Object visit(FilterFunction_equalTo filter, Object extraData) {
        Expression left = getParameter(filter, 0, true);
        Expression right = getParameter(filter, 1, true);
        Expression type = getParameter(filter, 2, true);
        String matchType = (String) type.evaluate(null);
        PropertyIsEqualTo equal =
                CommonFactoryFinder.getFilterFactory(null)
                        .equal(left, right, false, MatchAction.valueOf(matchType));
        if (isArrayType(left) && isArrayType(right) && matchType.equalsIgnoreCase("ANY")) {
            visitArrayComparison(
                    CommonFactoryFinder.getFilterFactory(null)
                            .equal(left, right, false, MatchAction.valueOf(matchType)),
                    left,
                    right,
                    null,
                    null,
                    "&&");
        } else {
            equal.accept(delegate, extraData);
        }
        return extraData;
    }

