@Override
    public int getGeometryDimension(
            String schemaName, String tableName, String columnName, Connection cx)
            throws SQLException {
        // first attempt, try with the geometry metadata
        Integer dimension = null;
        try (Statement statement = cx.createStatement()) {
            if (schemaName == null) schemaName = "public";

            // try geography_columns
            if (supportsGeography(cx)) {
                // first look for an entry in geography_columns
                String sqlStatement =
                        "SELECT COORD_DIMENSION FROM GEOGRAPHY_COLUMNS WHERE " //
                                + "F_TABLE_SCHEMA = '"
                                + schemaName
                                + "' " //
                                + "AND F_TABLE_NAME = '"
                                + tableName
                                + "' " //
                                + "AND F_GEOGRAPHY_COLUMN = '"
                                + columnName
                                + "'";
                LOGGER.log(Level.FINE, "Geography srid check; {0} ", sqlStatement);
                try (ResultSet result = statement.executeQuery(sqlStatement)) {

                    if (result.next()) {
                        return result.getInt(1);
                    }
                } catch (SQLException e) {
                    LOGGER.log(
                            Level.WARNING,
                            "Failed to retrieve information about "
                                    + schemaName
                                    + "."
                                    + tableName
                                    + "."
                                    + columnName
                                    + " from the geography_columns table, checking geometry_columns instead",
                            e);
                }
            }

            // try geometry_columns
            String sqlStatement =
                    "SELECT COORD_DIMENSION FROM GEOMETRY_COLUMNS WHERE " //
                            + "F_TABLE_SCHEMA = '"
                            + schemaName
                            + "' " //
                            + "AND F_TABLE_NAME = '"
                            + tableName
                            + "' " //
                            + "AND F_GEOMETRY_COLUMN = '"
                            + columnName
                            + "'";

            LOGGER.log(Level.FINE, "Geometry srid check; {0} ", sqlStatement);
            try (ResultSet result = statement.executeQuery(sqlStatement)) {
                if (result.next()) {
                    dimension = result.getInt(1);
                }
            } catch (SQLException e) {
                LOGGER.log(
                        Level.WARNING,
                        "Failed to retrieve information about "
                                + schemaName
                                + "."
                                + tableName
                                + "."
                                + columnName
                                + " from the geometry_columns table, checking the first geometry instead",
                        e);
            }
        }

        // fall back on inspection of the first geometry, assuming uniform srid (fair assumption
        // an unpredictable srid makes the table un-queriable)
        if (dimension == null) {
            dimension = getDimensionFromFirstGeo(schemaName, tableName, columnName, cx);
        }

        if (dimension == null) {
            dimension = 2;
        }

        return dimension;
    }

@Override
    public Object visit(PropertyName expression, Object extraData) throws RuntimeException {
        LOGGER.finer("exporting PropertyName");

        Class target = null;
        if (extraData instanceof Class) {
            target = (Class) extraData;
        }

        try {
            SimpleFeatureType featureType = this.featureType;

            // check for join
            if (expression instanceof JoinPropertyName) {
                // encode the prefix
                out.write(escapeName(((JoinPropertyName) expression).getAlias()));
                out.write(".");
            }

            // first evaluate expression against feautre type get the attribute,
            //  this handles xpath
            AttributeDescriptor attribute = null;
            EnumMapper mapper = null;
            try {
                attribute = (AttributeDescriptor) expression.evaluate(featureType);
                if (attribute != null) {
                    mapper = (EnumMapper) attribute.getUserData().get(JDBCDataStore.JDBC_ENUM_MAP);
                }
            } catch (Exception e) {
                // just log and fall back on just encoding propertyName straight up
                String msg = "Error occured mapping " + expression + " to feature type";
                LOGGER.log(Level.WARNING, msg, e);
            }

            // handle integer mapped enumerations
            if (mapper != null) {
                out.write("CASE ");
            }

            writeEncodedField(target, expression, attribute);

            // If we got here, it means the property is used inside some expression or function,
            // for this case we expand the property. For comparisons instead, the literal is
            // backmapped to an integer when possible, to allow index usage
            if (mapper != null) {
                out.write("\n ");
                for (Map.Entry<Integer, String> entry : mapper.getIntegerToString().entrySet()) {
                    out.write("WHEN " + entry.getKey() + " THEN '" + entry.getValue() + "'\n");
                }
                out.write("END");
            }

        } catch (java.io.IOException ioe) {
            throw new RuntimeException("IO problems writing attribute exp", ioe);
        }
        return extraData;
    }

void visitArrayComparison(
            BinaryComparisonOperator filter,
            Expression left,
            Expression right,
            Class rightContext,
            Class leftContext,
            String type) {
        String leftCast = "";
        String rightCast = "";
        if (left instanceof PropertyName) {
            rightCast = getArrayTypeCast((PropertyName) left);
        }
        if (right instanceof PropertyName) {
            leftCast = getArrayTypeCast((PropertyName) right);
        }

        try {
            // match any against non array literals? we need custom logic
            MultiValuedFilter.MatchAction matchAction = filter.getMatchAction();
            if ((matchAction == MultiValuedFilter.MatchAction.ANY
                            || matchAction == MultiValuedFilter.MatchAction.ONE)
                    && (!isArray(left) && !isArray(right))) {
                // the only indexable search in this block
                if ("=".equalsIgnoreCase(type) && !isNull(left) && !isNull(right)) {
                    // if using a prepared statement dialect we need the native type info
                    // contained in the AttributeDescriptor to create a SQL array...
                    Object leftArrayContext = getArrayComparisonContext(left, right, leftContext);
                    writeBinaryExpressionMember(left, leftArrayContext);
                    out.write(leftCast);
                    // use the overlap operator to avoid deciding which side is the expression
                    out.write(" && ");
                    Object rightArrayContext = getArrayComparisonContext(right, left, rightContext);
                    writeBinaryExpressionMember(right, rightArrayContext);
                    out.write(rightCast);
                } else {
                    // need to un-nest and apply element by element, this is not indexable
                    if (left instanceof PropertyName) {
                        rightContext = rightContext.getComponentType();
                    }
                    if (right instanceof PropertyName) {
                        leftContext = leftContext.getComponentType();
                    }

                    boolean isPropertyLeft = left instanceof PropertyName;
                    boolean isPropertyRight = right instanceof PropertyName;
                    // un-nesting the array to do element by element comparisons... the
                    // generated "table" has "unnest" as the variable name
                    if (matchAction == MultiValuedFilter.MatchAction.ANY) {
                        out.write("EXISTS ( SELECT * from unnest(");
                    } else {
                        out.write("( SELECT count(*) from unnest(");
                    }
                    if (isPropertyLeft) {
                        left.accept(delegate, null);
                    } else {
                        right.accept(delegate, null);
                    }
                    out.write(") WHERE ");
                    // oh fun, if there are nulls we cannot write the same sql
                    if ((isPropertyLeft && isNull(right))
                            || (isPropertyRight && isNull(left))
                                    && ("=".equalsIgnoreCase(type)
                                            || "!=".equalsIgnoreCase(type))) {
                        if ("=".equalsIgnoreCase(type)) {
                            out.write("unnest is NULL");
                        } else if ("!=".equalsIgnoreCase(type)) {
                            out.write("unnest is NOT NULL");
                        }
                    } else {
                        // no nulls, but we still have to consider the comparison direction
                        if (isPropertyLeft) {
                            out.write("unnest");
                            out.write(" " + type + " ");
                            writeBinaryExpressionMember(right, rightContext);
                        } else {
                            writeBinaryExpressionMember(left, leftContext);
                            out.write(" " + type + " ");
                            out.write("unnest");
                        }
                    }
                    if (matchAction == MultiValuedFilter.MatchAction.ONE) {
                        out.write(") = 1");
                    } else {
                        out.write(")");
                    }
                }
            } else if (matchAction == MultiValuedFilter.MatchAction.ALL
                    || isArray(left)
                    || isArray(right)) {
                // for comparison against array literals we only support match-all style
                // for the user it would be really strange to ask for equality on an array
                // and get a positive match on a partial element overlap (filters build
                // without explicit match action default to "ANY")
                Object leftArrayContext = getArrayComparisonContext(left, right, leftContext);
                writeBinaryExpressionMember(left, leftArrayContext);
                out.write(leftCast);
                out.write(" " + type + " ");
                Object rightArrayContext = getArrayComparisonContext(right, left, rightContext);
                writeBinaryExpressionMember(right, rightArrayContext);
                out.write(rightCast);
            }

        } catch (IOException ioe) {
            throw new RuntimeException("Failed to write out SQL", ioe);
        }
    }

