private void migrate103(File dataDir, Stack<Integer> versions) {
		VersionedXmlDoc projectUpdatesDom;
		File projectUpdatesFile = new File(dataDir, "ProjectUpdates.xml");
		projectUpdatesDom = new VersionedXmlDoc();
