public PersonIdent asPerson() {
		if (isSystem()) {
			return new PersonIdent(User.SYSTEM_NAME, User.SYSTEM_EMAIL_ADDRESS);
		} else {
			EmailAddress emailAddress = getGitEmailAddress();
			if (emailAddress != null && emailAddress.isVerified())
