private void migrate80(File dataDir, Stack<Integer> versions) {
		Map<String, Integer> issueCommentCounts = new HashMap<>();
		Map<String, Integer> pullRequestCommentCounts = new HashMap<>();

		for (File file: dataDir.listFiles()) {
